/**
 * Type utilities for PocketBase expanded relations.
 *
 * These types augment the autogenerated PocketBase types to handle cases where
 * relation fields are expanded into full record objects and flattened by the
 * afterSend hook.
 */

import type {
	PagesResponse,
	PostsResponse,
	TagsRecord,
	TagsResponse,
	UsersRecord,
	UsersResponse
} from './pocketbase';

/**
 * Augmented Pages type with author expanded and flattened
 */
export type PagesResponseWithAuthor = Omit<PagesResponse, 'author'> & {
	author?: UsersRecord | UsersResponse;
};

/**
 * Augmented Posts type with author and tags expanded and flattened
 */
export type PostsResponseWithExpanded = Omit<PostsResponse, 'author' | 'tags'> & {
	author: (UsersRecord | UsersResponse)[];
	tags: (TagsRecord | TagsResponse)[];
};
